importData();

import express from 'express';
import mongoose from 'mongoose';
import cors from 'cors';
import cookieParser from 'cookie-parser';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { Server as SocketServer } from 'socket.io';
import http from 'http';
import dotenv from 'dotenv';
import Resume from './models/Resume.js';
import User from './models/User.js';
import Message from './models/Message.js';

// Load biß║┐n m├┤i tr╞░ß╗¥ng
dotenv.config();

const app = express();
const httpServer = http.createServer(app);

const allowedOrigins = ['http://localhost:5173', 'http://localhost:4000', 'http://localhost:3000'];

// Cß║Ñu h├¼nh Socket.IO
const io = new SocketServer(httpServer, {
  cors: {
    origin: allowedOrigins,
    methods: ["GET", "POST"],
    credentials: true
  }
});
app.use(cors({ origin: allowedOrigins, credentials: true })); // Hß╗ù trß╗ú gß╗¡i Cookies qua lß║íi
app.use(cookieParser());
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Kß║┐t nß╗æi t├ái khoß║ún MongoDB Compass (Local)
const MONGO_URI = process.env.MONGO_URI || 'mongodb://127.0.0.1:27017/RabbitCV';

mongoose.connect(MONGO_URI, {
  serverSelectionTimeoutMS: 5000,  // Timeout nß║┐u kh├┤ng kß║┐t nß╗æi ─æ╞░ß╗úc sau 5s
  family: 4,                       // ├ëp d├╣ng IPv4 (tr├ính lß╗ùi ::1 vs 127.0.0.1)
})
  .then(() => console.log("Γ£à ─É├ú kß║┐t nß╗æi th├ánh c├┤ng tß╗¢i MongoDB!"))
  .catch(err => {
    console.log("Γ¥î Lß╗ùi kß║┐t nß╗æi MongoDB:", err.message);
  });

// Middleware x├íc thß╗▒c user
const authMiddleware = (req, res, next) => {
  const token = req.cookies.token;
  if (!token) return res.status(401).json({ message: "Vui l├▓ng ─æ─âng nhß║¡p" });

  try {
    const secret = process.env.JWT_SECRET || 'rabbitcv_secret_key_12345';
    const decoded = jwt.verify(token, secret);
    req.user = decoded; // { id, username, email }
    next();
  } catch (err) {
    res.status(401).json({ message: "Phi├¬n ─æ─âng nhß║¡p hß║┐t hß║ín!" });
  }
};

// Lß║Ñy danh s├ích Tß║ñT Cß║ó c├íc CV cß╗ºa user n├áy
app.get('/api/resumes', authMiddleware, async (req, res) => {
  try {
    const resumes = await Resume.find({ userId: req.user.id }).sort({ updatedAt: -1 });
    res.status(200).json(resumes);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Thiß║┐t lß║¡p API lß║Ñy 1 CV Cß╗Ñ thß╗â
app.get('/api/resume/:id', authMiddleware, async (req, res) => {
  try {
    const resume = await Resume.findOne({ _id: req.params.id, userId: req.user.id });
    if (resume) {
      res.status(200).json(resume);
    } else {
      res.status(404).json({ message: "Kh├┤ng t├¼m thß║Ñy dß╗» liß╗çu CV" });
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Th├¬m API l╞░u CV mß╗¢i HOß║╢C l╞░u ch├¿n v├áo CV c┼⌐ (nß║┐u gß╗¡i id)
app.post('/api/resume', authMiddleware, async (req, res) => {
  try {
    const data = req.body;

    // Kiß╗âm tra kh├┤ng cho ph├⌐p tr├╣ng t├¬n CV
    const titleCheck = await Resume.findOne({ title: data.title, userId: req.user.id });
    if (titleCheck && (!data._id || titleCheck._id.toString() !== data._id)) {
      return res.status(400).json({ message: "T├¬n CV n├áy ─æ├ú tß╗ôn tß║íi! Vui l├▓ng chß╗ìn mß╗Öt t├¬n kh├íc." });
    }

    if (data._id) {
      // Nß║┐u frontend gß╗¡i id l├¬n -> User ─æang chß╗ënh sß╗¡a mß╗Öt bß║ún CV ─æ├ú c├│ sß║╡n
      let resume = await Resume.findOne({ _id: data._id, userId: req.user.id });
      if (resume) {
        Object.assign(resume, data);
        await resume.save();
        return res.status(200).json({ message: "Cß║¡p nhß║¡t CV th├ánh c├┤ng", resume });
      }
    }

    // Nß║┐u kh├┤ng gß╗¡i id -> User tß║ío mß╗¢i
    const newResume = new Resume({ ...data, userId: req.user.id });
    await newResume.save();
    res.status(200).json({ message: "Tß║ío CV mß╗¢i th├ánh c├┤ng", resume: newResume });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// API X├│a 1 bß║ún CV
app.delete('/api/resume/:id', authMiddleware, async (req, res) => {
  try {
    const deleted = await Resume.findOneAndDelete({ _id: req.params.id, userId: req.user.id });
    if (!deleted) return res.status(404).json({ message: "Kh├┤ng t├¼m thß║Ñy CV ─æß╗â x├│a" });
    res.status(200).json({ message: "─É├ú x├│a CV th├ánh c├┤ng!" });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// API ─É─âng k├╜
app.post('/api/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;

    // Validation c╞í bß║ún
    if (!username || !email || !password) {
      return res.status(400).json({ message: "Vui l├▓ng nhß║¡p ─æß║ºy ─æß╗º th├┤ng tin!" });
    }

    // Kiß╗âm tra xem ─æ├ú tß╗ôn tß║íi ch╞░a
    const existingUser = await User.findOne({ $or: [{ username }, { email }] });
    if (existingUser) {
      return res.status(400).json({ message: "T├¬n ─æ─âng nhß║¡p hoß║╖c Email ─æ├ú tß╗ôn tß║íi!" });
    }

    // Hash mß║¡t khß║⌐u
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);

    // L╞░u user
    const newUser = new User({ username, email, password: hashedPassword });
    await newUser.save();

    res.status(201).json({ message: "─É─âng k├╜ t├ái khoß║ún th├ánh c├┤ng!" });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// API ─É─âng nhß║¡p
app.post('/api/login', async (req, res) => {
  try {
    const { username, password, rememberMe } = req.body;

    if (!username || !password) {
      return res.status(400).json({ message: "T├¬n ─æ─âng nhß║¡p v├á mß║¡t khß║⌐u l├á bß║»t buß╗Öc!" });
    }

    const user = await User.findOne({ username });
    if (!user) {
      return res.status(400).json({ message: "T├ái khoß║ún kh├┤ng tß╗ôn tß║íi!" });
    }

    // Kiß╗âm tra mß║¡t khß║⌐u
    const isMatch = await bcrypt.compare(password, user.password);
    if (!isMatch) {
      return res.status(400).json({ message: "Mß║¡t khß║⌐u kh├┤ng ch├¡nh x├íc!" });
    }

    // Cß║Ñp JWT
    const secret = process.env.JWT_SECRET || 'rabbitcv_secret_key_12345';
    const payload = { id: user._id, username: user.username, email: user.email };

    // Nß║┐u Remember Me th├¼ jwt sß╗æng 30 ng├áy, ng╞░ß╗úc lß║íi 1 ng├áy
    const expiresIn = rememberMe ? '30d' : '1d';
    const token = jwt.sign(payload, secret, { expiresIn });

    // C├ái HTTP-Only Cookie
    const cookieOptions = {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: rememberMe ? 30 * 24 * 60 * 60 * 1000 : 24 * 60 * 60 * 1000
    };

    res.cookie('token', token, cookieOptions);
    res.status(200).json({ message: "─É─âng nhß║¡p th├ánh c├┤ng!", user: payload });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// API X├íc thß╗▒c tß╗½ tr├¼nh duyß╗çt v├á lß║Ñy Info user ─æang login
app.get('/api/me', authMiddleware, (req, res) => {
  res.status(200).json({ user: req.user });
});

// API ─É─âng xuß║Ñt
app.post('/api/logout', (req, res) => {
  res.clearCookie('token');
  res.status(200).json({ message: "─É├ú ─æ─âng xuß║Ñt!" });
});

// API Lß║Ñy lß╗ïch sß╗¡ tin nhß║»n
app.get('/api/messages', async (req, res) => {
  try {
    const room = req.query.room || 'general';
    const messages = await Message.find({ room }).sort({ createdAt: 1 }).limit(100);
    res.status(200).json(messages);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Quß║ún l├╜ kß║┐t nß╗æi WebSocket
io.on('connection', (socket) => {
  console.log('ΓÜí User connected:', socket.id);

  // Ng╞░ß╗¥i d├╣ng tham gia 1 ph├▓ng (mß║╖c ─æß╗ïnh l├á general)
  socket.on('join_room', (room) => {
    socket.join(room);
    console.log(`User ${socket.id} joined room: ${room}`);
  });

  // Sß╗▒ kiß╗çn gß╗¡i tin nhß║»n
  socket.on('send_message', async (data) => {
    try {
      // Tß║ío tin nhß║»n mß╗¢i
      const newMessage = new Message({
        senderId: data.senderId,
        senderName: data.senderName,
        content: data.content,
        room: data.room || 'general'
      });

      // Ph├ít lß║íi tin nhß║»n ─æ├│ cho tß║Ñt cß║ú ng╞░ß╗¥i d├╣ng trong ph├▓ng ngay lß║¡p tß╗⌐c (Real-time m╞░ß╗út m├á h╞ín)
      io.to(newMessage.room).emit('receive_message', newMessage);

      // Sau ─æ├│ mß╗¢i l╞░u tin nhß║»n v├áo DB
      await newMessage.save();
    } catch (error) {
      console.error('Lß╗ùi khi gß╗¡i/l╞░u tin nhß║»n:', error);
    }
  });

  socket.on('disconnect', () => {
    console.log('Γ¥î User disconnected:', socket.id);
  });
});

const PORT = process.env.PORT || 5000;
httpServer.listen(PORT, () => console.log(`≡ƒÜÇ Server ─æang chß║íy tß║íi: http://localhost:${PORT}`));

