import React from "react";
import {
  EnvelopeIcon,
  PhoneIcon,
  MapPinIcon,
  GlobeAltIcon,
} from "@heroicons/react/24/outline";

// Helper for displaying contact items
const ContactItem = ({ icon: Icon, text, link }) => {
  if (!text) return null;
  const content = (
    <div className="flex items-center gap-1.5 text-xs text-slate-600">
      <Icon className="w-3.5 h-3.5 shrink-0" />
      <span className="truncate">{text}</span>
    </div>
  );
  return link ? <a href={link} target="_blank" rel="noreferrer" className="hover:text-blue-600">{content}</a> : content;
};

// Helper for sidebar contact items
const SidebarContactItem = ({ icon: Icon, text, link }) => {
  if (!text) return null;
  const content = (
    <div className="flex items-center gap-2 text-xs text-slate-300">
      <Icon className="w-4 h-4 text-slate-400 shrink-0" />
      <span className="truncate">{text}</span>
    </div>
  );
  return link ? <a href={link} target="_blank" rel="noreferrer" className="hover:text-white">{content}</a> : content;
};

