function Login() {
  const navigate = useNavigate();
  const showToast = useToastContext();
  const [formData, setFormData] = useState({
    username: "",
    password: "",
    rememberMe: false,
  });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    if (!formData.username || !formData.password) {
      setError("Vui l├▓ng nhß║¡p t├¬n ─æ─âng nhß║¡p v├á mß║¡t khß║⌐u.");
      return;
    }

    try {
      setLoading(true);
      const res = await fetch("http://localhost:5000/api/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include", // D├╣ng include ─æß╗â set v├á gß╗¡i HttpOnly token cookie
        body: JSON.stringify({
          username: formData.username,
          password: formData.password,
          rememberMe: formData.rememberMe,
        }),
      });
      const data = await res.json();

      if (res.ok) {
        showToast("─É─âng nhß║¡p th├ánh c├┤ng!", "success");
        setTimeout(() => navigate("/WelcomePageCustomer"), 800);
      } else {
        setError(data.message || "T├ái khoß║ún hoß║╖c mß║¡t khß║⌐u kh├┤ng ch├¡nh x├íc.");
      }
    } catch (err) {
      setError("Lß╗ùi kß║┐t nß╗æi ─æß║┐n m├íy chß╗º.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full min-h-screen bg-linear-to-br from-[#F8F4FC] to-[#E8DCFA] flex flex-col">
      <HeaderNoUser />

      <div className="flex-1 flex flex-col items-center justify-center">
        <div className="flex flex-col items-center mb-6">
          <img
            alt="RabbitCV Logo"
            src="../RabbitCV.png"
            className="h-16 w-16 mb-3"
          />
          <h1 className="text-2xl font-bold text-[#9346F5]">─É─âng nhß║¡p</h1>
        </div>

        <form className="w-full max-w-sm" onSubmit={handleSubmit}>
          <div className="bg-white p-6 rounded-3xl shadow-xl space-y-4">
            
            {error && (
              <div className="bg-red-50 text-red-600 p-3 rounded-xl text-sm font-medium border border-red-100 text-center">
                {error}
              </div>
            )}

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  T├¬n ─æ─âng nhß║¡p
                </label>
                <input
                  type="text"
                  name="username"
                  value={formData.username}
                  onChange={handleChange}
                  className="w-full border-2 border-gray-300 px-3 py-2.5 rounded-xl focus:border-[#9346F5] focus:outline-none focus:ring-2 focus:ring-[#9346F5]/20 transition-all duration-200"
                  placeholder="Nhß║¡p t├¬n ─æ─âng nhß║¡p"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">
                  Mß║¡t khß║⌐u
                </label>
                <input
                  type="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  className="w-full border-2 border-gray-300 px-3 py-2.5 rounded-xl focus:border-[#9346F5] focus:outline-none focus:ring-2 focus:ring-[#9346F5]/20 transition-all duration-200"
                  placeholder="Nhß║¡p mß║¡t khß║⌐u"
                />
              </div>

              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <input
                    type="checkbox"
                    id="remember"
                    name="rememberMe"
                    checked={formData.rememberMe}
                    onChange={handleChange}
                    className="w-4 h-4 text-[#9346F5] border-gray-300 rounded focus:ring-[#9346F5] cursor-pointer"
                  />
                  <label
                    htmlFor="remember"
                    className="ml-2 text-sm text-gray-700 cursor-pointer"
                  >
                    Ghi nhß╗¢ ─æ─âng nhß║¡p
                  </label>
                </div>
                <a
                  href="#"
                  className="text-sm text-[#9346F5] hover:text-[#7c38c9] font-semibold transition-colors"
                >
                  Qu├¬n mß║¡t khß║⌐u?
