import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import Header from "../Components/Header";
import ResumeForm from "../Components/ResumeForm";
import ResumePreview from "../Components/ResumePreview";
import ResumeTemplate from "../Components/ResumeTemplate";
import {
  ChevronDoubleLeftIcon,
  ChevronDoubleRightIcon,
  CheckCircleIcon,
  ExclamationCircleIcon,
} from "@heroicons/react/24/outline";

function Toast({ message, type }) {
  if (!message) return null;
  const isSuccess = type === "success";
  return (
    <div className={`fixed bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-3 px-5 py-3 rounded-2xl shadow-2xl text-sm font-semibold transition-all duration-300 ${
      isSuccess ? "bg-green-500 text-white" : "bg-red-500 text-white"
    }`}>
      {isSuccess
        ? <CheckCircleIcon className="w-5 h-5 shrink-0" />
        : <ExclamationCircleIcon className="w-5 h-5 shrink-0" />}
      {message}
    </div>
  );
}

export default function CreateResume() {
  const location = useLocation();
  const [showForm, setShowForm] = useState(true);
  const [showTemplates, setShowTemplates] = useState(true);
  const [_id, setId] = useState(location.state?.cvId || null);
  const [title, setTitle] = useState("CV Mß╗¢i Cß╗ºa T├┤i");
  const [selectedTemplate, setSelectedTemplate] = useState(location.state?.template || "modern");
  const [toast, setToast] = useState({ message: "", type: "success" });

  const showToast = (message, type = "success") => {
    setToast({ message, type });
    setTimeout(() => setToast({ message: "", type }), 3000);
  };

  const [image, setImage] = useState(null);
  const [bio, setBio] = useState("");
  const [personalInfo, setPersonalInfo] = useState({
    fullName: "",
    jobTitle: "",
    email: "",
    website: "",
    phone: "",
    location: "",
  });
  const [profile, setProfile] = useState([]);
  const [experience, setExperience] = useState([]);
  const [education, setEducation] = useState([]);
  const [skill, setSkill] = useState([]);
  const [language, setLanguage] = useState([]);
  const [certificate, setCertificate] = useState([]);
  const [project, setProject] = useState([]);
  const [award, setAward] = useState([]);
  const [hobby, setHobby] = useState([]);


  useEffect(() => {
    const fetchResumeData = async () => {
      // Nß║┐u kh├┤ng c├│ _id truyß╗ün tß╗½ ResumeSelection, ngh─⌐a l├á tß║ío mß╗¢i -> Kh├┤ng fetch
      if (!_id) return;
      
      try {
        const response = await fetch(`http://localhost:5000/api/resume/${_id}`, {
          credentials: "include"
        });
        
        if (response.ok) {
          const data = await response.json();
          if (data) {
            const mapId = (arr) => arr?.map(item => ({ ...item, id: item._id || item.id })) || [];
            setTitle(data.title || "CV Mß╗¢i Cß╗ºa T├┤i");
            setImage(data.image || "");
            setPersonalInfo(data.personalInfo || personalInfo);
            setBio(data.bio || bio);
            setProfile(data.profile ? mapId(data.profile) : profile);
            setExperience(data.experience ? mapId(data.experience) : experience);
            setEducation(data.education ? mapId(data.education) : education);
            setSkill(data.skill ? mapId(data.skill) : skill);
            setLanguage(data.language ? mapId(data.language) : language);
            setCertificate(data.certificate ? mapId(data.certificate) : certificate);
            setProject(data.project ? mapId(data.project) : project);
            setAward(data.award ? mapId(data.award) : award);
            setHobby(data.hobby ? mapId(data.hobby) : hobby);
          }
        }
      } catch (error) {
        console.error("Lß╗ùi khi kß║┐t nß╗æi API lß║Ñy dß╗» liß╗çu:", error);
      }
    };

    fetchResumeData();
  }, [_id]);

  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const payload = {
        title,
        image,
        personalInfo,
        bio,
        profile,
        experience,
        education,
        skill,
        language,
        certificate,
        project,
        award,
        hobby
      };
      
      if (_id) payload._id = _id;

      const response = await fetch("http://localhost:5000/api/resume", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        credentials: "include",
        body: JSON.stringify(payload)
      });
      if (response.ok) {
        const responseData = await response.json();
        if (responseData.resume?._id) setId(responseData.resume._id);
        showToast("L╞░u CV v├áo Database th├ánh c├┤ng! Γ£ô", "success");
      } else {
        const errorData = await response.json();
        showToast(errorData.message || "Lß╗ùi khi l╞░u CV, vui l├▓ng thß╗¡ lß║íi.", "error");
      }
    } catch (error) {
      console.error("Lß╗ùi khi gß╗¡i dß╗» liß╗çu:", error);
      showToast("Kh├┤ng thß╗â kß║┐t nß╗æi ─æß║┐n server!", "error");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="bg-[#F8F4FC] h-screen flex flex-col">
      <Header />
      <Toast message={toast.message} type={toast.type} />
      <div className="flex flex-1 overflow-hidden relative">
        {/* Left Sidebar Toggle */}
        <button
          onClick={() => setShowForm(!showForm)}
          className={`absolute top-4 z-20 bg-white p-1 rounded-r-lg shadow-md hover:bg-gray-50 transition-all duration-300 ${
            showForm ? "left-[30%]" : "left-0"
          }`}
          title={showForm ? "Thu gß╗ìn Form" : "Mß╗ƒ rß╗Öng Form"}
        >
          {showForm ? (
            <ChevronDoubleLeftIcon className="w-5 h-5 text-gray-600" />
          ) : (
            <ChevronDoubleRightIcon className="w-5 h-5 text-gray-600" />
          )}
        </button>

        {/* Left Sidebar (Resume Form) */}
        <div
          className={`transition-all duration-300 ease-in-out border-r border-gray-200 bg-white overflow-hidden ${
            showForm ? "w-[30%]" : "w-0"
          }`}
        >
          <div className="w-full h-full overflow-y-auto">
            <ResumeForm
              image={image}
              setImage={setImage}
              personalInfo={personalInfo}
              setPersonalInfo={setPersonalInfo}
              bio={bio}
              setBio={setBio}
              profile={profile}
              setProfile={setProfile}
              experience={experience}
              setExperience={setExperience}
              education={education}
              setEducation={setEducation}
              skill={skill}
              setSkill={setSkill}
              language={language}
              setLanguage={setLanguage}
              certificate={certificate}
              setCertificate={setCertificate}
              project={project}
              setProject={setProject}
              award={award}
              setAward={setAward}
              hobby={hobby}
              setHobby={setHobby}
            />
          </div>
        </div>

        {/* Center Canvas (Preview) */}
        <div className="flex-1 bg-gray-100 overflow-hidden flex flex-col items-center py-8 relative">
          <div className="absolute top-6 right-8 left-8 z-10 flex justify-between gap-4 pointer-events-none">
            {/* Input ─Éß║╖t T├¬n CV */}
            <div className="pointer-events-auto">
              <input
                 type="text"
                 value={title}
                 onChange={(e) => setTitle(e.target.value)}
                 placeholder="Nhß║¡p t├¬n CV..."
                 className="px-4 py-2 border-2 border-black rounded-xl text-sm font-bold shadow-sm focus:outline-none focus:ring-4 focus:ring-purple-500/20 w-64 bg-white"
              />
            </div>

            <button
              onClick={handleSave}
              disabled={isSaving}
              className={`pointer-events-auto text-white px-5 py-2.5 rounded-xl shadow-lg transition-all text-sm font-bold flex items-center justify-center gap-2 border-2 border-black/10 ${
                isSaving ? "bg-purple-400 cursor-not-allowed" : "bg-black hover:bg-[#9346F5] hover:border-black active:scale-95 duration-200"
              }`}
            >
              {isSaving ? "─Éang l╞░u..." : "L╞░u CV N├áy"}
            </button>
          </div>
          <ResumePreview
            selectedTemplate={selectedTemplate}
            image={image}
            personalInfo={personalInfo}
            bio={bio}
            profile={profile}
            experience={experience}
            education={education}
            skill={skill}
            language={language}
            certificate={certificate}
            project={project}
            award={award}
            hobby={hobby}
          />
        </div>

        {/* Right Sidebar Toggle */}
        <button
          onClick={() => setShowTemplates(!showTemplates)}
          className={`absolute top-4 z-20 bg-white p-1 rounded-l-lg shadow-md hover:bg-gray-50 transition-all duration-300 ${
            showTemplates ? "right-[20%]" : "right-0"
          }`}
          title={showTemplates ? "Thu gß╗ìn Templates" : "Mß╗ƒ rß╗Öng Templates"}
        >
          {showTemplates ? (
            <ChevronDoubleRightIcon className="w-5 h-5 text-gray-600" />
          ) : (
            <ChevronDoubleLeftIcon className="w-5 h-5 text-gray-600" />
          )}
        </button>

        {/* Right Sidebar (Templates) */}
        <div
          className={`transition-all duration-300 ease-in-out border-l border-gray-200 bg-white overflow-hidden ${
            showTemplates ? "w-[20%]" : "w-0"
          }`}
        >
          <ResumeTemplate
            selectedTemplate={selectedTemplate}
            setSelectedTemplate={setSelectedTemplate}
          />
        </div>
      </div>
    </div>
  );
}

